import React from "react";
import { useDispatch, useSelector } from "react-redux";
import PageCreator from "../../components/PageCreator";
import {
  getAllGreetings,
  createGreeting,
  deleteGreeting,
  updateGreeting,
  uploadGreetingImages,
  getGreetingImages,
} from "../../redux/action/greetingActions";
// import DateRangePicker from "react-bootstrap-daterangepicker";
import { useParams } from "react-router";
import CommonAction from "../../components/Common/Actions/CommonAction";
import CommonActionModal from "../../components/Common/Modals/CommonActionModal";
import ImageIcon from "@material-ui/icons/ImageTwoTone";
import { greetingTypes } from "../../redux/types";
const Greeting = () => {
  const dispatch = useDispatch();
  const { greetings: data } = useSelector((state) => state.greeting);
  const [uploadOpen, setUploadOpen] = React.useState();
  const [images, setImages] = React.useState([]);

  const { id } = useParams();

  const handleOpenUpload = async (data) => {
    await dispatch(getGreetingImages(data.id)).then((res) => {
      if (res.payload.status === 200) {
        setImages(res.payload.data.data);
        setUploadOpen({ ...data, images: res.payload.data.data });
      }
    });
  };
  const handleCloseUpload = () => {
    setUploadOpen();
    setImages([]);
  };

  const handleUploadSubmit = (data) => {
    dispatch(
      uploadGreetingImages(
        {
          ...data,
          id: uploadOpen.id || uploadOpen._id,
          categoryId: uploadOpen.categoryId,
        },
        () => {
          handleCloseUpload();
        }
      )
    );
  };
  const CommonActionBtn = (action) => (
    <CommonAction
      onClick={(row) => handleOpenUpload(action.data)}
      title="Upload Images"
      children={<ImageIcon />}
    />
  );
  const formData = [
    {
      type: "text",
      name: "greetingName",
      label: "Greeting Name",
      placeholder: "Type Greeting Name",
      required: true,
      size: 12,
      required: true,
    },

    {
      type: "select",
      name: "status",
      size: 12,

      label: "Status",
      options: [
        {
          title: "Active",
          value: "true",
        },
        {
          title: "Inactive",
          value: "false",
        },
      ],
      optionLabelProp: "title",
      optionValueProp: "value",
      required: true,
    },
    {
      type: "switch",
      name: "isHomePage",
      label: "Display in home screen",
      required: true,
      size: 12,
      required: true,
    },
    // {
    //   type: "file",
    //   name: "subcategoryImage",
    //   label: "Greeting Image",
    //   placeholder: "Type Greeting Image",
    //   required: true,
    //   size: 12,
    // },
  ];

  const tableHeaders = [
    // { title: "Image", key: "subcategoryImage", type: "image" },
    { title: "Name", key: "greetingName" },
    { title: "Status", key: "status" },
  ];

  const pageProps = {
    title: "Greetings",
    layout: "tabular",
    formData: formData,
    tableHeaders: tableHeaders,
    tableData: data,
    searchByField: ["greetingName"],
    searchByLabel: "name",
    modalSize: "xs",
    sortable: true,

    paginated: true,
    tableRowActions: [CommonActionBtn],
    // hideEdit: false,
    // hideDelete: true,
    // hideAdd: true,
    // hideView: true,

    onAdd: (data, cb, errorCb) =>
      createGreeting({ ...data, categoryId: id }, cb, errorCb),
    onEdit: updateGreeting,
    onDelete: deleteGreeting,

    getData: (e) => getAllGreetings(id),
    loadingTypes: [
      greetingTypes.CREATE_GREETINGS,
      greetingTypes.UPDATE_GREETINGS,
    ],
  };
  React.useEffect(() => {
    dispatch(getAllGreetings(id));
  }, [id]);
  const imagesFormdata = [
    {
      type: "file",
      name: "images",
      label: "Image",
      placeholder: "Type Image",
      required: true,
      multiple: true,
      size: 12,
    },
  ];
  const loadingTypes = greetingTypes.UPLOAD_GREETING_IMAGES;

  return (
    <>
      {imagesFormdata && (
        <CommonActionModal
          formData={imagesFormdata}
          title={"Upload Images"}
          open={Boolean(uploadOpen)}
          onClose={() => handleCloseUpload()}
          mode={"edit"}
          onSubmit={(e) => handleUploadSubmit(e)}
          data={uploadOpen}
          size={"md"}
          loadingType={loadingTypes}
          // data={{ images: images }}
          // defaultValues={{ images: images }}
        />
      )}

      <PageCreator {...pageProps} />
    </>
  );
};

export default Greeting;
