import React from "react";
import { useDispatch, useSelector } from "react-redux";
import PageCreator from "../../components/PageCreator";
import {
  getAllSubcategories,
  createSubcategory,
  deleteSubcategory,
  updateSubcategory,
  uploadSubcategoryImages,
  getSubCateImages,
  sendNotification,
} from "../../redux/action/subcategoryActions";
import AddAlertIcon from "@material-ui/icons/AddAlert";

import { useParams } from "react-router";
import { getAllCategories } from "../../redux/action/categoryActions";
import CommonAction from "../../components/Common/Actions/CommonAction";
import CommonActionModal from "../../components/Common/Modals/CommonActionModal";
import ImageIcon from "@material-ui/icons/ImageTwoTone";
import { IconButton, Tooltip } from "@material-ui/core";
import { subcategoryTypes } from "../../redux/types";
const Categories = () => {
  const dispatch = useDispatch();
  const { subcategories: data, subImages } = useSelector(
    (state) => state.subcategory
  );
  const [uploadOpen, setUploadOpen] = React.useState();
  const [images, setImages] = React.useState([]);

  const { id } = useParams();

  const handleOpenUpload = async (data) => {
    await dispatch(getSubCateImages(data.id)).then((res) => {
      if (res.payload.status === 200) {
        setImages(res.payload.data.data);
        setUploadOpen({ ...data, images: res.payload.data.data });
      }
    });
  };
  const handleCloseUpload = () => {
    setUploadOpen();
    setImages([]);
  };

  const handleUploadSubmit = (data) => {
    dispatch(
      uploadSubcategoryImages(
        {
          ...data,
          id: uploadOpen.id || uploadOpen._id,
          categoryId: uploadOpen.categoryId,
        },
        () => {
          handleCloseUpload();
        }
      )
    );
  };
  const CommonActionBtn = (action) => (
    <CommonAction
      onClick={(row) => handleOpenUpload(action.data)}
      title="Upload Images"
      children={<ImageIcon />}
    />
  );
  const formData = [
    {
      type: "text",
      name: "subcategoryName",
      label: "Subcategory Name",
      placeholder: "Type Subcategory Name",
      required: true,
      size: 12,
      required: true,
    },
    {
      type: "number",
      name: "priority",
      label: "Priority",
      placeholder: "Type Priority",
      required: true,
      size: 12,
      required: true,
    },
    {
      type: "select",
      name: "status",
      size: 12,

      label: "Status",
      options: [
        {
          title: "Active",
          value: "true",
        },
        {
          title: "Inactive",
          value: "false",
        },
      ],
      optionLabelProp: "title",
      optionValueProp: "value",
      required: true,
    },
    // {
    //   type: "file",
    //   name: "subcategoryImage",
    //   label: "Subcategory Image",
    //   placeholder: "Type Subcategory Image",
    //   required: true,
    //   size: 12,
    // },
  ];

  const tableHeaders = [
    // { title: "Image", key: "subcategoryImage", type: "image" },
    { title: "Name", key: "subcategoryName" },
    { title: "Priority", key: "priority" },
    { title: "Status", key: "status" },
  ];

  const handleNotify = (data) => {
    dispatch(sendNotification(data));
  };

  const NotificationAction = (action) => {
    return (
      <Tooltip placement="top" title="Send Notification">
        <IconButton color="primary" onClick={() => handleNotify(action.data)}>
          <AddAlertIcon />
        </IconButton>
      </Tooltip>
    );
  };

  const pageProps = {
    title: "Subcategories",
    layout: "tabular",
    formData: formData,
    tableHeaders: tableHeaders,
    tableData: data,
    searchByField: ["subcategoryName"],
    searchByLabel: "name",
    modalSize: "xs",
    sortable: true,

    paginated: true,
    tableRowActions: [CommonActionBtn, NotificationAction],
    // hideEdit: false,
    // hideDelete: true,
    // hideAdd: true,
    // hideView: true,

    onAdd: (data, cb, errorCb) =>
      createSubcategory({ ...data, categoryId: id }, cb, errorCb),
    onEdit: updateSubcategory,
    onDelete: deleteSubcategory,

    getData: (e) => getAllSubcategories(id),
    loadingTypes: [
      subcategoryTypes.CREATE_SUBCATEGORIES,
      subcategoryTypes.UPDATE_SUBCATEGORIES,
    ],
  };
  React.useEffect(() => {
    dispatch(getAllSubcategories(id));
    dispatch(getAllCategories(true));
  }, [id]);
  const imagesFormdata = [
    {
      type: "file",
      name: "images",
      label: "Image",
      placeholder: "Type Image",
      required: true,
      multiple: true,
      size: 12,
    },
  ];

  const loadingTypes = subcategoryTypes.UPLOAD_SUBCATEGORY_IMAGES;

  return (
    <>
      {imagesFormdata && (
        <CommonActionModal
          formData={imagesFormdata}
          title={"Upload Images"}
          open={Boolean(uploadOpen)}
          onClose={() => handleCloseUpload()}
          mode={"edit"}
          onSubmit={(e) => handleUploadSubmit(e)}
          data={uploadOpen}
          size={"md"}
          loadingType={loadingTypes}
          // data={{ images: images }}
          // defaultValues={{ images: images }}
        />
      )}

      <PageCreator {...pageProps} />
    </>
  );
};

export default Categories;
